"""Triton implementation of aten::_foreach_maximum_.ScalarList.

In-place: for every i, self[i] = max_NaN(self[i], scalars[i]) where the scalar is
wrapped to self[i].dtype by PyTorch wrapped-number semantics.  NaN propagates
(torch.maximum semantics) and the result is always exactly one of the operands.

Layout strategy
---------------
* four contiguous tensors of the same dtype and size share one launch: each
  program applies the same tile offset to all four buffers, so the grid is 4x
  smaller than a slot-per-program mapping and every program has four
  independent tile transfers in flight.
* the comparison happens in the buffer's own element dtype: the scalar is
  pre-rounded on the host to exactly the wrapped value, so no fp32 promotion of
  fp16/bf16 data is needed.  Full tiles drop the bounds mask entirely.
* arbitrary strided views (noncontiguous accuracy cases) use a general
  stride-decomposition kernel with a small tile so the UB budget is safe.
"""

import math
import numbers
import struct

import torch
import triton
import triton.language as tl

_BLOCK = 8192
_BLOCK_STRIDED = 256
_KSLOTS = 4
_MAX_DIMS = 8


