@triton.jit
def _max_tile_even(base, s, pid, BLOCK: tl.constexpr):
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    offs = tl.max_contiguous(tl.multiple_of(offs, BLOCK), BLOCK)
    sv = s.to(base.dtype.element_ty)
    x = tl.load(base + offs)
    tl.store(base + offs, tl.maximum(x, sv, propagate_nan=tl.PropagateNan.ALL))


@triton.jit
def _max_tile(base, n, s, pid, BLOCK: tl.constexpr, EVEN: tl.constexpr):
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    offs = tl.max_contiguous(tl.multiple_of(offs, BLOCK), BLOCK)
    sv = s.to(base.dtype.element_ty)
    if EVEN:
        x = tl.load(base + offs)
        tl.store(base + offs, tl.maximum(x, sv, propagate_nan=tl.PropagateNan.ALL))
    else:
        m = offs < n
        x = tl.load(base + offs, mask=m)
        tl.store(
            base + offs,
            tl.maximum(x, sv, propagate_nan=tl.PropagateNan.ALL),
            mask=m,
        )


@triton.jit
def _fmax_quad_even_k(
    p0,
    p1,
    p2,
    p3,
    s0,
    s1,
    s2,
    s3,
    BLOCK: tl.constexpr,
):
    """Four equal, full tiles per program: smallest grid, no bounds mask.

    All four loads are issued before the first store so the block has four
    independent transfers outstanding instead of a load/store chain.
    """
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    offs = tl.max_contiguous(tl.multiple_of(offs, BLOCK), BLOCK)
    x0 = tl.load(p0 + offs)
    x1 = tl.load(p1 + offs)
    t0 = s0.to(p0.dtype.element_ty)
    t1 = s1.to(p1.dtype.element_ty)
    tl.store(p0 + offs, tl.maximum(x0, t0, propagate_nan=tl.PropagateNan.ALL))
    tl.store(p1 + offs, tl.maximum(x1, t1, propagate_nan=tl.PropagateNan.ALL))
    x2 = tl.load(p2 + offs)
    x3 = tl.load(p3 + offs)
    t2 = s2.to(p2.dtype.element_ty)
    t3 = s3.to(p3.dtype.element_ty)
    tl.store(p2 + offs, tl.maximum(x2, t2, propagate_nan=tl.PropagateNan.ALL))
    tl.store(p3 + offs, tl.maximum(x3, t3, propagate_nan=tl.PropagateNan.ALL))


@triton.jit
def _fmax_quad_k(
    p0,
    p1,
    p2,
    p3,
    n,
    s0,
    s1,
    s2,
    s3,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    _max_tile(p0, n, s0, pid, BLOCK, False)
    _max_tile(p1, n, s1, pid, BLOCK, False)
    _max_tile(p2, n, s2, pid, BLOCK, False)
    _max_tile(p3, n, s3, pid, BLOCK, False)


@triton.jit
def _fmax_single_k(base, n, s, BLOCK: tl.constexpr, EVEN: tl.constexpr):
    _max_tile(base, n, s, tl.program_id(0), BLOCK, EVEN)


@triton.jit
def _fmax_fused_k(
    p0,
    p1,
    p2,
    p3,
    n0,
    n1,
    n2,
    n3,
    s0,
    s1,
    s2,
    s3,
    c0,
    c1,
    c2,
    BLOCK: tl.constexpr,
    EVEN: tl.constexpr,
):
    pid = tl.program_id(0)
    if pid < c0:
        _max_tile(p0, n0, s0, pid, BLOCK, EVEN)
    elif pid < c1:
        _max_tile(p1, n1, s1, pid - c0, BLOCK, EVEN)
    elif pid < c2:
        _max_tile(p2, n2, s2, pid - c1, BLOCK, EVEN)
    else:
        _max_tile(p3, n3, s3, pid - c2, BLOCK, EVEN)


@triton.jit
def _fmax_strided_k(
    base,
    n,
    s,
    sh0,
    sh1,
    sh2,
    sh3,
    sh4,
    sh5,
    sh6,
    sh7,
    st0,
    st1,
    st2,
    st3,
    st4,
    st5,
    st6,
    st7,
    NDIM: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < n
    rem = offs
    off = tl.zeros((BLOCK,), dtype=tl.int32)
    if NDIM > 7:
        q = rem % sh7
        rem = rem // sh7
        off += q * st7
    if NDIM > 6:
        q = rem % sh6
        rem = rem // sh6
        off += q * st6
    if NDIM > 5:
        q = rem % sh5
        rem = rem // sh5
        off += q * st5
    if NDIM > 4:
        q = rem % sh4
        rem = rem // sh4
        off += q * st4
    if NDIM > 3:
        q = rem % sh3
        rem = rem // sh3
        off += q * st3
    if NDIM > 2:
        q = rem % sh2
        rem = rem // sh2
        off += q * st2
    if NDIM > 1:
        q = rem % sh1
        rem = rem // sh1
        off += q * st1
    if NDIM > 0:
        off += rem * st0
    sv = s.to(base.dtype.element_ty)
    x = tl.load(base + off, mask=m)
    r = tl.where(x != x, x, tl.where(x > sv, x, sv))
    tl.store(base + off, r, mask=m)


# ---------------------------------------------------------------------------
# host helpers
# ---------------------------------------------------------------------------


def _to_fp16(v):
    try:
        return float(struct.unpack("e", struct.pack("e", v))[0])
    except OverflowError:
        return math.inf if v > 0 else -math.inf


def _to_fp32(v):
    try:
        return float(struct.unpack("f", struct.pack("f", v))[0])
    except OverflowError:
        return math.inf if v > 0 else -math.inf


def _to_bf16(v):
    # round-to-nearest-even from fp32 to bfloat16, returned as an exactly
    # representable Python float
    try:
        bits = struct.unpack("I", struct.pack("f", v))[0]
    except OverflowError:
        return math.inf if v > 0 else -math.inf
    if (bits & 0x7F800000) == 0x7F800000 and (bits & 0x007FFFFF):
        return float("nan")
    lsb = (bits >> 16) & 1
    bits = (bits + 0x7FFF + lsb) & 0xFFFF0000
    return float(struct.unpack("f", struct.pack("I", bits))[0])


def _wrap_scalar(value, dtype):
    if isinstance(value, torch.Tensor):
        value = value.item()
    if dtype.is_floating_point:
        v = float(value)
        if v != v:
            return v
        if dtype == torch.float16:
            return _to_fp16(v)
        if dtype == torch.bfloat16:
            return _to_bf16(v)
        if dtype == torch.float32:
            return _to_fp32(v)
        return v
    if dtype == torch.bool:
        return 1 if value else 0
    return int(value)


def _collapsed(shape, strides):
    """Drop size-1 dims, order by descending stride, merge contiguous runs.

    The merged run keeps the *inner* stride: after ordering, a run merges when
    the outer stride continues the inner run, and the fused dim then walks
    memory with the inner (smallest) stride.
    """
    dims = [(int(sz), int(st)) for sz, st in zip(shape, strides) if int(sz) != 1]
    if not dims:
        return [(1, 1)]
    dims = sorted(dims, key=lambda p: -p[1])
    merged = []
    for sz, st in dims:
        if merged and merged[-1][1] == st * sz:
            psz, _ = merged[-1]
            merged[-1] = (psz * sz, st)
        else:
            merged.append((sz, st))
    return merged


def _launch_quad(t0, t1, t2, t3, v0, v1, v2, v3, n, dtype):
    if dtype == torch.float32:
        # Triton rounds a Python float to fp32 exactly like the reference wrap.
        s0 = v0 if v0.__class__ is float else _to_fp32(float(v0))
        s1 = v1 if v1.__class__ is float else _to_fp32(float(v1))
        s2 = v2 if v2.__class__ is float else _to_fp32(float(v2))
        s3 = v3 if v3.__class__ is float else _to_fp32(float(v3))
    else:
        s0 = _wrap_scalar(v0, dtype)
        s1 = _wrap_scalar(v1, dtype)
        s2 = _wrap_scalar(v2, dtype)
        s3 = _wrap_scalar(v3, dtype)
    if n % _BLOCK:
        grid = ((n + _BLOCK - 1) // _BLOCK,)
        _fmax_quad_k[grid](t0, t1, t2, t3, n, s0, s1, s2, s3, BLOCK=_BLOCK)
    else:
        _fmax_quad_even_k[(n // _BLOCK,)](t0, t1, t2, t3, s0, s1, s2, s3, BLOCK=_BLOCK)


def _launch_group(tensors, ss, i, j):
    L = j - i
    total = 0
    chunks = []
    for k in range(i, j):
        c = (tensors[k].numel() + _BLOCK - 1) // _BLOCK
        chunks.append(c)
        total += c
    even = True
    for k in range(i, j):
        if tensors[k].numel() % _BLOCK != 0:
            even = False
            break
    dtype = tensors[i].dtype
    dummy = 0 if not dtype.is_floating_point else 0.0
    p = [tensors[i]] * _KSLOTS
    nn = [0] * _KSLOTS
    sv = [dummy] * _KSLOTS
    for k in range(L):
        p[k] = tensors[i + k]
        nn[k] = p[k].numel()
        sv[k] = _wrap_scalar(ss[i + k], dtype)
    acc = 0
    cum = [0, 0, 0]
    for k in range(3):
        if k < L - 1:
            acc += chunks[k]
            cum[k] = acc
        else:
            cum[k] = total
    _fmax_fused_k[(total,)](
        p[0],
        p[1],
        p[2],
        p[3],
        nn[0],
        nn[1],
        nn[2],
        nn[3],
        sv[0],
        sv[1],
        sv[2],
        sv[3],
        cum[0],
        cum[1],
        cum[2],
        BLOCK=_BLOCK,
        EVEN=even,
    )


def _launch_strided(t, sc, n):
    s = _wrap_scalar(sc, t.dtype)
    dims = _collapsed(t.shape, t.stride())
    nd = len(dims)
    if nd == 1 and dims[0] == (n, 1):
        grid = ((n + _BLOCK - 1) // _BLOCK,)
        _fmax_single_k[grid](t, n, s, BLOCK=_BLOCK, EVEN=(n % _BLOCK == 0))
        return
    if nd > _MAX_DIMS:
        raise RuntimeError("unsupported tensor rank for strided foreach maximum")
    sh = [1] * _MAX_DIMS
    st = [0] * _MAX_DIMS
    for k, (sz, stride) in enumerate(dims):
        sh[k] = sz
        st[k] = stride
    grid = ((n + _BLOCK_STRIDED - 1) // _BLOCK_STRIDED,)
    _fmax_strided_k[grid](t, n, s, *sh, *st, NDIM=nd, BLOCK=_BLOCK_STRIDED)


def foreach_maximum_scalar_list_(self, scalars):
    tensors = self if isinstance(self, (list, tuple)) else list(self)
    if isinstance(scalars, (list, tuple)):
        slist = scalars
    elif isinstance(scalars, numbers.Number) or (
        isinstance(scalars, torch.Tensor) and scalars.ndim == 0
    ):
        slist = [scalars] * len(tensors)
    else:
        slist = list(scalars)
    nt = len(tensors)
    if len(slist) != nt:
        raise RuntimeError("Tensor list length must equal scalar list length.")

    i = 0
    while i < nt:
        t = tensors[i]
        n = t.numel()
        if n == 0:
            i += 1
            continue
        if not t.is_contiguous():
            _launch_strided(t, slist[i], n)
            i += 1
            continue
        dtype = t.dtype
        if i + _KSLOTS <= nt:
            t1 = tensors[i + 1]
            t2 = tensors[i + 2]
            t3 = tensors[i + 3]
            if (
                t1.numel() == n
                and t2.numel() == n
                and t3.numel() == n
                and t1.dtype == dtype
                and t2.dtype == dtype
                and t3.dtype == dtype
                and t1.is_contiguous()
                and t2.is_contiguous()
                and t3.is_contiguous()
            ):
                _launch_quad(
                    t,
                    t1,
                    t2,
                    t3,
                    slist[i],
                    slist[i + 1],
                    slist[i + 2],
                    slist[i + 3],
                    n,
                    dtype,
                )
                i += _KSLOTS
                continue
        j = i + 1
        while j < nt and j - i < _KSLOTS:
            tj = tensors[j]
            if tj.dtype != dtype or tj.numel() == 0 or not tj.is_contiguous():
                break
            j += 1
        _launch_group(tensors, slist, i, j)
        i = j
    return None
